def render(name, kind, pages):
    path = OUT / name
    c = canvas.Canvas(str(path), pagesize=landscape(A4))
    c.setTitle('FIT-LAB - ' + kind)
    c.setAuthor('FIT-LAB')
    w, h = landscape(A4)
    styles = {
        'body': ParagraphStyle('body', fontName='Guide', fontSize=10.5, leading=14.4, textColor=HexColor('#30363b')),
        'small': ParagraphStyle('small', fontName='Guide', fontSize=9, leading=12, textColor=HexColor('#60676c')),
    }
    def para(text, x, y, width, style='body'):
        p = Paragraph(text, styles[style]); _, height = p.wrap(width, 600)
        p.drawOn(c, x, y-height)
        return y-height
    for number, data in enumerate(pages, 1):
        c.setFillColor(HexColor('#f8f6f1')); c.rect(0, 0, w, h, fill=1, stroke=0)
        c.setFillColor(HexColor('#181b1e')); c.rect(0, h-115, w, 115, fill=1, stroke=0)
        c.setFillColor(HexColor('#ffc16c')); c.setFont('GuideBold', 16); c.drawString(34,h-32,'FIT-LAB')
        c.setFont('Guide',9);c.drawRightString(w-34,h-31,data['intro'])
        c.setFillColor(HexColor('#f7f4eb'));c.setFont('GuideBold',25);c.drawString(34,h-78,data['title'])
        c.setStrokeColor(HexColor('#d6d0c5')); c.line(34,38,w-34,38)
        c.setFillColor(HexColor('#757b80'));c.setFont('Guide',8)
        c.drawString(34,23,f'FIT-LAB Station | {DATE} | {kind} | Закрытый пользовательский комплект')
        c.drawRightString(w-34,23,f'{number} / {len(pages)}')
        items = data['items']
        if data['image']:
            img = IMAGES / (data['image']+'-1380x850.png')
            c.drawImage(str(img),34,163,width=462,height=285,preserveAspectRatio=True,anchor='c',mask='auto')
            para('Иллюстрация интерфейса. Показания и доступные поля зависят от оборудования.',34,150,462,'small')
            y = 460
            for title, body in items:
                y = para('<b>'+escape(title)+'</b><br/>'+escape(body),520,y,w-554)-16
            assert y > 106, (name, number, y)
        else:
            split = (len(items)+1)//2
            for col, group in enumerate((items[:split], items[split:])):
                x = 34 + col * 393
                y = 460
                for title, body in group:
                    c.setFillColor(HexColor('#e5aa5a'));c.roundRect(x,y-4,24,3,1.5,fill=1,stroke=0)
                    y = para('<b>'+escape(title)+'</b><br/>'+escape(body),x,y-14,360)-22
                assert y > 109, (name, number, y)
        if data['note']:
            y = para(escape(data['note']),34,98,w-68,'small')
            assert y > 48, (name, number, y)
        c.showPage()
    c.save()
    return path


def main():
    OUT.mkdir(parents=True, exist_ok=True)
    pdfmetrics.registerFont(TTFont('Guide', '/System/Library/Fonts/Supplemental/Arial.ttf'))
    pdfmetrics.registerFont(TTFont('GuideBold', '/System/Library/Fonts/Supplemental/Arial Bold.ttf'))
    pdfmetrics.registerFontFamily('Guide', normal='Guide', bold='GuideBold')
    import sys
    guide_only = '--guide-only' in sys.argv
    for filename, kind, pages in (
        ('FIT-LAB - инструкция.pdf', 'Инструкция', GUIDE),
        ('FIT-LAB - чек-лист.pdf', 'Чек-лист', CHECK),
        ('FIT-LAB - отчёт.pdf', 'Отчёт о работе', REPORT),
    ):
        if guide_only and kind != 'Инструкция':
            continue
        print(render(filename,kind,pages))
        md = OUT / ('Чек-лист.md' if kind=='Чек-лист' else 'Отчёт о работе.md' if kind.startswith('Отчёт') else 'Инструкция.md')
        md.write_text('# FIT-LAB - '+kind+'\n\n'+DATE+'\n\n'+'\n\n'.join(
            '## '+p['title']+'\n\n'+'\n\n'.join('### '+t+'\n\n'+b for t,b in p['items'])+'\n\n'+p['note'] for p in pages)+'\n')
    (OUT/'Дополнение — веб-плеер.md').write_text('# Веб-плеер FIT-LAB\n\nОбновлено '+DATE+'. Полные актуальные инструкции включены в «FIT-LAB - инструкция.pdf», разделы 5 и 6.\n\nАдрес текущей станции: http://192.168.50.1:8890/\nЗапись вручную: Запись → Остановить запись → Сохранить.\nСистемное автооткрытие окна iPhone пока не внедрено.\n')
    (OUT/'Состав комплекта.json').write_text(json.dumps(dict(updated=DATE, documents=3, pages=len(GUIDE)+len(CHECK)+len(REPORT),
        guide_pages=len(GUIDE), checklist_pages=len(CHECK), report_pages=len(REPORT), secrets_included=False,
        licensing='planned_not_implemented', camera1_acceptance='password_verified_key_renewal_rolled_back',camera2_password='verified'),ensure_ascii=False,indent=2)+'\n')


if __name__ == '__main__':
    main()
